def clean(x,key=''):
 if isinstance(x,dict):return {k:clean(v,k) for k,v in x.items()}
 if isinstance(x,list):return [clean(v,key) for v in x]
 if isinstance(x,str) and not key.endswith('En') and not key in ['url','id']:
  for a,b in replacements.items():x=x.replace(a,b)
 return x
